import Testing
import Foundation
@testable import Noto

/// Golden vectors generated by running celyn's own `questionKey` /
/// `normalizeName` (`src/lib/koi/core.ts`, `src/lib/normalize.ts`) under node.
/// If celyn changes its normalisation, both sides must change together.
@Suite("QuizKey")
struct QuizKeyTests {

    @Test("golden vectors shared with celyn", arguments: [
        ("Quel film est sorti en premier ?", ["B", "A", "C", "D"],
         "quel film est sorti en premier#a|b|c|d"),
        ("Qui a écrit « Les Fourberies de Scapin » ?", ["Molière", "Racine", "Corneille", "Marivaux"],
         "qui a ecrit les fourberies de scapin#corneille|marivaux|moliere|racine"),
        ("L'Œuvre au noir : qui en est l'autrice ?", ["Marguerite Yourcenar", "Colette", "George Sand", "Annie Ernaux"],
         "uvre au noir qui en est l autrice#annie ernaux|colette|george sand|marguerite yourcenar"),
        ("Le théorème de Pythagore s'applique à quel triangle ?", ["Rectangle", "Isocèle", "Équilatéral", "Quelconque"],
         "theoreme de pythagore s applique a quel triangle#equilateral|isocele|quelconque|rectangle"),
        ("Combien font 2 + 2 × 3 ?", ["12", "8", "10", "6"],
         "combien font 2 2 3#10|12|6|8"),
    ])
    func golden(question: String, choices: [String], expected: String) {
        #expect(QuizKey.make(question: question, choices: choices) == expected)
    }

    @Test("celyn's own test: case, accents and punctuation fold; the choice set matters")
    func celynCoreTest() {
        let k1 = QuizKey.make(question: "Quel film est sorti en premier ?", choices: ["B", "A", "C", "D"])
        #expect(k1 == QuizKey.make(question: "QUEL FILM EST SORTI EN PREMIER", choices: ["a", "b", "c", "d"]))
        #expect(k1 != QuizKey.make(question: "Quel film est sorti en premier ?", choices: ["A", "B", "C", "E"]))
    }

    @Test("choice order does not change the key")
    func choiceOrder() {
        let q = "Qui a peint La Joconde ?"
        #expect(QuizKey.make(question: q, choices: ["Vinci", "Raphaël", "Titien", "Botticelli"])
                == QuizKey.make(question: q, choices: ["Botticelli", "Titien", "Vinci", "Raphaël"]))
    }

    @Test("question cut to 240, whole key cut to 500 (celyn vector)")
    func truncation() {
        let key = QuizKey.make(question: String(repeating: "x", count: 300),
                               choices: [String(repeating: "a", count: 200), String(repeating: "b", count: 200), "c", "d"])
        let expected = String(repeating: "x", count: 240) + "#" + String(repeating: "a", count: 200) + "|"
            + String(repeating: "b", count: 58)
        #expect(key == expected)
        #expect(key.count == 500)
    }

    @Test("only one leading article is stripped", arguments: [
        ("Les Misérables", "miserables"), ("the The End", "the end"), ("L’Étranger", "etranger"),
        ("Lettres", "lettres"), ("  Le Cid", "le cid"),
    ])
    func articles(input: String, expected: String) {
        #expect(QuizKey.normalizeName(input) == expected)
    }

    @Test("deterministic v5 id: stable, version 5, distinct per key")
    func deterministicID() {
        let key = "quel film est sorti en premier#a|b|c|d"
        let id = QuizKey.deterministicID(for: key)
        #expect(id == QuizKey.deterministicID(for: key))
        #expect(id != QuizKey.deterministicID(for: key + "x"))
        let s = id.uuidString
        #expect(s[s.index(s.startIndex, offsetBy: 14)] == "5")
        #expect("89AB".contains(s[s.index(s.startIndex, offsetBy: 19)]))
    }
}
